<?php $pageTitle='Seating allocation'; ?>
<?php if($allocation['status']!=='published'):?><section class="panel no-print"><div class="form-section-heading"><p class="eyebrow">Manual correction</p><h2>Move an assigned student</h2><p>Every correction is marked as a manual override and written to the audit trail.</p></div><form class="form-grid three" method="post" action="<?= e(url('seating/'.$allocation['id'].'/move')) ?>"><?= csrf_field() ?><label>Current assignment<select name="assignment_id" required><option value="">Select student</option><?php foreach($assignments as $item):?><option value="<?= (int)$item['id'] ?>"><?= e($item['roll_no_original'].' - '.$item['room_code'].'/'.$item['seat_label']) ?></option><?php endforeach;?></select></label><label>New vacant seat<select name="seat_id" required><option value="">Select seat</option><?php foreach($availableSeats as $seat):?><option value="<?= (int)$seat['id'] ?>"><?= e($seat['room_code'].' / '.$seat['seat_label']) ?></option><?php endforeach;?></select></label><label>Reason<input name="reason" required placeholder="Operational correction"><button class="secondary-button">Move student</button></label></form></section><?php endif;?>
<?php if($unallocated):?><section class="panel table-panel no-print"><div class="form-section-heading"><p class="eyebrow">Capacity exception report</p><h2>Unallocated students</h2><p>Assign a newly available vacant seat or include these students in the exported exception report.</p></div><div class="table-scroll"><table><thead><tr><th>Roll number</th><th>Name</th><th>Programme</th><th>Paper</th><th>Resolution</th></tr></thead><tbody><?php foreach($unallocated as $item):?><tr><td><strong><?= e($item['roll_no_original']) ?></strong></td><td><?= e($item['name']) ?></td><td><?= e($item['programme_code']) ?></td><td><?= e($item['course_code']) ?></td><td><?php if($allocation['status']!=='published'):?><form class="inline-form" method="post" action="<?= e(url('seating/'.$allocation['id'].'/assign-unallocated')) ?>"><?= csrf_field() ?><input type="hidden" name="unallocated_id" value="<?= (int)$item['id'] ?>"><select name="seat_id" required><option value="">Vacant seat</option><?php foreach($availableSeats as $seat):?><option value="<?= (int)$seat['id'] ?>"><?= e($seat['room_code'].'/'.$seat['seat_label']) ?></option><?php endforeach;?></select><button class="text-button">Assign</button></form><?php else:?>Requires a new allocation version<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<section class="page-heading no-print"><div><p class="eyebrow">Version <?= (int)$allocation['version_no'] ?></p><h1><?= e($allocation['cycle_name']) ?></h1><p><?= e(date('d F Y',strtotime($allocation['exam_date'])).' - '.$allocation['shift_name']) ?></p></div><div class="heading-actions"><a class="secondary-button" href="javascript:window.print()">Print all rooms</a><?php if($allocation['status']!=='published'):?><form method="post" action="<?= e(url('seating/'.$allocation['id'].'/publish')) ?>"><?= csrf_field() ?><button class="primary-button" <?= !$validation['valid']?'disabled':'' ?>>Publish allocation</button></form><?php endif;?></div></section><?php if($success):?><div class="alert success no-print"><?= e($success) ?></div><?php endif;?><?php if($error):?><div class="alert error no-print"><?= e($error) ?></div><?php endif;?><section class="validation-strip no-print"><strong><?= $validation['valid']?'Validation passed':'Validation failed' ?></strong><?php foreach($validation as $name=>$value):if($name==='valid')continue;?><span><?= e(str_replace('_',' ',$name)) ?>: <?= (int)$value ?></span><?php endforeach;?></section><?php foreach($byRoom as $roomCode=>$items):$rows=[];$summary=[];foreach($items as $item){$rows[$item['row_no']][$item['column_no']]=$item;$key=$item['programme_code'].'|'.$item['course_code'].'|'.$item['course_name'];$summary[$key]=($summary[$key]??0)+1;}?><section class="seating-sheet"><header><strong>Seating Plan (SOICT)</strong><h2>Room No - <?= e($roomCode) ?></h2><p><?= e($allocation['shift_name'].' ('.substr($allocation['start_time'],0,5).' - '.substr($allocation['end_time'],0,5).') '.date('d-m-Y',strtotime($allocation['exam_date']))) ?></p></header><div class="whiteboard">WHITE BOARD</div><div class="allocation-grid"><?php foreach($rows as $row=>$columns):?><div class="allocation-row"><?php foreach($columns as $column=>$item):?><div><small><?= e($item['desk_group']) ?> / <?= e($item['seat_label']) ?></small><strong><?= e($item['roll_no_original']) ?></strong><span><?= e($item['programme_code'].' - '.$item['course_code']) ?></span></div><?php endforeach;?></div><?php endforeach;?></div><table class="seating-summary"><thead><tr><th>S.No.</th><th>Student detail</th><th>No. of Students</th></tr></thead><tbody><?php $n=1;foreach($summary as $key=>$count):[$programme,$code,$name]=explode('|',$key,3);?><tr><td><?= $n++ ?></td><td><?= e($programme.' - '.$code.' '.$name) ?></td><td><?= $count ?></td></tr><?php endforeach;?><tr><td></td><td><strong>Total</strong></td><td><strong><?= count($items) ?></strong></td></tr></tbody></table></section><?php endforeach;?>
